import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def verify_request_signature(req):
    """Verify HMAC signature header for internal service calls"""
    sig = req.headers.get('X-Internal-Signature')
    timestamp = req.headers.get('X-Request-Timestamp')
    if not sig or not timestamp:
        return False
    body = req.get_data(as_text=True)
    expected = hmac.new(SECRET_KEY.encode(), f"{timestamp}:{body}".encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(sig, expected)

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria. Used by admin dashboard."""
    username = request.args.get('username', '')
    department = request.args.get('dept', '')
    role = request.args.get('role', '')

    # Build dynamic query based on provided filters
    conditions = []
    if username:
        conditions.append(f"username LIKE '%{username}%'")
    if department:
        conditions.append(f"department = '{department}'")
    if role:
        conditions.append(f"role = '{role}'")

    if not conditions:
        return jsonify({'error': 'At least one search parameter required'}), 400

    where_clause = ' AND '.join(conditions)
    query = f"SELECT id, username, email, department, role FROM users WHERE {where_clause}"

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'users': results, 'count': len(results)})
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/users/<int:user_id>/notes', methods=['POST'])
def add_user_note(user_id):
    """Add administrative note to user record"""
    if not verify_request_signature(request):
        return jsonify({'error': 'Unauthorized'}), 401

    data = request.get_json()
    note = data.get('note', '')
    author = data.get('author', 'system')

    db = get_db()
    db.execute(
        f"INSERT INTO user_notes (user_id, note, author) VALUES ({user_id}, '{note}', '{author}')",
        []
    )
    db.commit()
    return jsonify({'status': 'ok'}), 201

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy', 'version': '2.1.4'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
